INSERT OR IGNORE INTO bitacora_criterio (id, tema, decision, fundamento, quien, fecha, estado, observaciones) VALUES
('C1', 'ISR catorcenal', 'Base ÷ 14, tarifa diaria, subsidio diario, × 14', 'Equivale a la tarifa por día × 14 del catálogo; el Anexo 8 no publica tarifa de 14 días', 'Rafael González', '2026-10-14', 'vigente', '15-oct: la regla exacta da 2,207.47 (emp 191 cat. 16) y 62,868.17 (bono emp 89); la nómina dio 2,207.49 y 62,868.21. La proyección mensual (× 30.4 ÷ 14, tarifa mensual, regreso) reproduce 2,207.49 exacto y da 62,868.2158 en el bono: la diferencia es de método, no de redondeo. Además el caso escrito «4,490.58 × 14 = 62,868.21» no cuadra aritméticamente (da 62,868.12). Confirmar con Rafael qué método aplica la nómina de PRIME.'),
('C2', 'Subsidio en semanal y catorcenal', 'Monto y tope proporcionales a los días del periodo; ajuste mensual en la última nómina del mes con monto y tope mensuales', 'Decreto DOF 31-dic-2025', 'Rafael González', '2026-10-14', 'por_confirmar', 'Divisor 30.4, no 30 (corrección 1): por confirmar con Rafael.'),
('C3', 'Despensa en CDMX', 'Sin efecto para PRIME: ya no paga vales; agosto viene en ceros. La contradicción del cuadro sigue abierta para otros clientes', 'Nota de Rafael y prenómina de agosto', 'Rafael González', '2026-10-14', 'vigente', NULL),
('C4', 'Rango de CEAV', 'SBC ÷ UMA truncado a dos decimales, como el SUA', '4,104 de 4,104 líneas del SUA; 1,034 renglones en 2.51–3.00 y ninguno al 3.150%', 'Evidencia de agosto', '2026-10-14', 'por_confirmar', NULL),
('C5', 'Pagos extra', 'Corrida aparte con la tarifa del periodo sobre el pago solo', '99 de 99 en agosto', 'Evidencia de agosto', '2026-10-14', 'por_confirmar', 'Falta cómo entran al ajuste mensual: sólo 16 de 53 cuadran.'),
('C6', 'Base gravable cero o negativa', 'ISR cero y traza con caso_borde; el arrastre al periodo siguiente no se decide aún', 'Módulo 8, casos borde', 'Pendiente (Claudio / Rafael)', '2026-10-15', 'abierto', NULL),
('C7', 'Subsidios por incapacidad (ISR)', 'Se tratan como gravados y el cálculo queda limitado hasta decidir', 'LISR art. 93 fr. VIII', 'Pendiente (Rafael)', '2026-10-15', 'abierto', NULL),
('C8', 'Ausentismos por rama', 'No se descuentan; el cálculo queda limitado cuando hay ausentismos', 'LSS art. 31; PRIME no los registra en el SUA', 'Pendiente (Rafael)', '2026-10-15', 'abierto', NULL);
